def _source_path(relative):
    installed = jit_env.FLASHINFER_CSRC_DIR / relative.removeprefix("csrc/")
    checkout = Path(__file__).resolve().parents[2] / relative
    if installed.is_file():
        return installed
    if checkout.is_file():
        return checkout
    raise FileNotFoundError(f"generated SiTU source is not installed: {relative}")


@cache
def gen_cake_situ_module(program_key):
    record = PROGRAMS[program_key]
    exact_target_flags = {
        "sm_100a": sm100a_nvcc_flags,
        "sm_103a": sm103a_nvcc_flags,
    }[record["arch"]]
    sources = [_source_path(path) for path in record["sources"]]
    checkout_root = Path(__file__).resolve().parents[2]
    include_dir = jit_env.FLASHINFER_INCLUDE_DIR
    if not include_dir.is_dir():
        include_dir = checkout_root / "include"
    include_paths = list(dict.fromkeys([
        *(source.parent for source in sources),
        jit_env.FLASHINFER_CSRC_DIR,
        checkout_root / "csrc",
        include_dir,
    ]))
    flags = list(record["compile_flags"])
    spec = gen_jit_spec(
        record["cache_name"],
        sources=sources,
        extra_cuda_cflags=[*exact_target_flags, *flags],
        extra_include_paths=include_paths,
    )
    # gen_jit_spec adds fast math for ordinary FlashInfer kernels. The source
    # compiler does not enable it by default: retain exactly the exported
    # semantic setting, including an explicitly authored fast-math option.
    if not any(flag in {"-use_fast_math", "--use_fast_math"} for flag in flags):
        spec.extra_cuda_cflags = [
            flag for flag in spec.extra_cuda_cflags
            if flag not in {"-use_fast_math", "--use_fast_math"}
        ]
    return spec


@cache
def get_cake_situ_module(program_key):
    return gen_cake_situ_module(program_key).build_and_load()


def cake_situ_sequence(arch, tile_n, single_token, feature_finalize, m64_claim8=False, mid_work5fd=False, n32_claim8=False, m256_c12=False):
    selector = ("m256_c12" if m256_c12 else "m64_claim8" if m64_claim8 else "mid_work5fd" if mid_work5fd else "n32_claim8" if n32_claim8 else
                "m1" if single_token else "n8_feature" if feature_finalize else tile_n)
    return ROUTES[(arch, selector)]
